-- ===== cross_field_discount_code.sql =====
-- cross-field rule violated: discount_code required if status == "cancelled"
-- Generated by `contractgate export dbt-tests` from rule `cross_field:discount_code`.
-- A non-empty result fails this test (dbt singular test convention).
select *
from {{ ref('orders') }}
where ("status" = 'cancelled' and "discount_code" is null)
-- ===== cross_field_updated_at.sql =====
-- cross-field rule violated: updated_at >= created_at
-- Generated by `contractgate export dbt-tests` from rule `cross_field:updated_at`.
-- A non-empty result fails this test (dbt singular test convention).
select *
from {{ ref('orders') }}
where ("updated_at" is not null and "created_at" is not null and not ("updated_at" >= "created_at"))
-- ===== freshness_created_at.sql =====
-- created_at is older than the freshness window (604800 seconds)
-- Generated by `contractgate export dbt-tests` from rule `freshness:created_at`.
-- A non-empty result fails this test (dbt singular test convention).
select *
from {{ ref('orders') }}
where ("created_at" is not null and "created_at" < (now() - interval '604800 seconds'))
-- ===== length_discount_code.sql =====
-- discount_code length must be between 4 and 20
-- Generated by `contractgate export dbt-tests` from rule `length:discount_code`.
-- A non-empty result fails this test (dbt singular test convention).
select *
from {{ ref('orders') }}
where ("discount_code" is not null and (length("discount_code") < 4 or length("discount_code") > 20))
